Create core/workflow_engine.py with classes for workflow management:

```python
class WorkflowState:
    def __init__(self, initial_state=None):
        self.state = initial_state or {}

    def update(self, key, value):
        self.state[key] = value

    def get(self, key, default=None):
        return self.state.get(key, default)

class WorkflowStep:
    def __init__(self, name, agent, input_mapping=None, output_mapping=None):
        self.name = name
        self.agent = agent
        self.input_mapping = input_mapping or {}
        self.output_mapping = output_mapping or {}

    def execute(self, workflow_state):
        # Map inputs from workflow state
        inputs = {}
        for target_key, source_key in self.input_mapping.items():
            inputs[target_key] = workflow_state.get(source_key)

        # Run the agent
        result = self.agent.run(inputs, workflow_state.state)

        # Map outputs to workflow state
        for target_key, source_key in self.output_mapping.items():
            if source_key in result:
                workflow_state.update(target_key, result[source_key])

        return result

class Workflow:
    def __init__(self, name, steps=None):
        self.name = name
        self.steps = steps or []
        self.state = WorkflowState()

    def add_step(self, step):
        self.steps.append(step)

    def run(self, initial_state=None):
        if initial_state:
            self.state = WorkflowState(initial_state)

        results = []
        for step in self.steps:
            result = step.execute(self.state)
            results.append(result)

        return results, self.state.state
```

