```python
import json
import os

class NotebookOrchestrator:
    def __init__(self, data_dir="./data"):
        self.data_dir = data_dir
        self.state_file = os.path.join(data_dir, "notebook_state.json")
        self.state = self._load_state()

    def _load_state(self):
        if os.path.exists(self.state_file):
            with open(self.state_file, "r") as f:
                return json.load(f)
        return {
            "current_notebook": "bienvenida.ipynb",
            "completed_notebooks": [],
            "restaurant_id": None,
            "data": {}
        }

    def save_state(self):
        os.makedirs(self.data_dir, exist_ok=True)
        with open(self.state_file, "w") as f:
            json.dump(self.state, f, indent=2)

    def update_state(self, key, value):
        self.state["data"][key] = value
        self.save_state()

    def get_state(self, key, default=None):
        return self.state["data"].get(key, default)

    def complete_notebook(self, notebook_name):
        if notebook_name not in self.state["completed_notebooks"]:
            self.state["completed_notebooks"].append(notebook_name)
        self.save_state()

    def set_current_notebook(self, notebook_name):
        self.state["current_notebook"] = notebook_name
        self.save_state()

    def get_next_notebook(self):
        notebook_sequence = [
            "bienvenida.ipynb",
            "Clasificación.ipynb",
            "Configuración_inicial.ipynb",
            "alineamiento.ipynb",
            "Estructura.ipynb",
            "manual_operativo.ipynb"
        ]
        current_index = notebook_sequence.index(self.state["current_notebook"])
        if current_index < len(notebook_sequence) - 1:
            return notebook_sequence[current_index + 1]
        return None
```

